+static void apply_move(const state_t *src, state_t *dst,
+                       uint8_t face, uint8_t turns)
+{
+    const uint8_t *from = move_source[face][turns - 1];
+    const uint8_t *delta = move_twist[face][turns - 1];
+    for (int i = 0; i < CUBIES; ++i) {
+        uint8_t j = from[i];
+        dst->p[i] = src->p[j];
