+/* Lehmer code: map the seven-corner permutation to 0..5039. */
+static int permutation_index(const state_t *state)
+{
+    int rank = 0;
+    for (int i = 0; i < CUBIES; ++i) {
+        int smaller = 0;
+        for (int j = i + 1; j < CUBIES; ++j)
+            if (state->p[j] < state->p[i])
